class Fetch{static async call(e,r,c="POST"){return await fetch(e,{method:c,mode:"same-origin",cache:"no-cache",credentials:"same-origin",headers:{"Content-Type":"application/json"},redirect:"follow",referrerPolicy:"no-referrer",body:JSON.stringify(r)}).then(e=>e.json()).catch(e=>e)}}